package com.margelo.nitro.bridgewebview
  
import com.facebook.proguard.annotations.DoNotStrip
import android.util.Log
import java.util.List

@DoNotStrip
class NitroBridgeWebview : HybridNitroBridgeWebviewSpec() {
  override fun multiply(a: Double, b: Double, input: String): String {
    Log.d("YANNICK", "🌈 Hello" + input)
    var millis = System.currentTimeMillis()
    StaticMessages.Messages.add("New Value")
    Log.d("YANNICK", StaticMessages.Messages.toString())
    // return a * b
    var payload = ""

    return millis.toString() + "/AAA" + payload + payload + payload + payload + payload + payload
    return "a * b"
  }

  override fun addPayload(id: String, input: String): Unit {
    Log.d("YANNICK", "🌈 Call AddPayload with " + id + " - " + input)
  }

  override fun getPayload(id: String): String {
    Log.d("YANNICK", "🌈 Call GetPayload with " + id)

    return "nothing"
  }
}
